+function requestLanguage(headers) {
+  const key = Object.keys(headers).find((name) => name.toLowerCase() === "accept-language");
+  let language = config.defaultLanguage;
+  let bestQuality = 0;
+  for (const entry of String(headers[key] ?? "").split(",")) {
+    const range = /^([a-z]+)(?:-[a-z0-9]{1,8})*(?:\s*;\s*q=(0(?:\.\d{0,3})?|1(?:\.0{0,3})?))?$/i.exec(entry.trim());
+    if (!range) continue;
+    const primary = range[1].toLowerCase();
+    const quality = Number(range[2] ?? 1);
+    if (LANGUAGES.includes(primary) && quality > bestQuality) {
+      language = primary;
+      bestQuality = quality;
+    }
+  }
+  return language;
+}
